import Vue, { PropType } from 'vue';
import QueryString from 'qs';
import axios, { AxiosPromise } from 'axios';
import { IOperatorTheme } from '@game-studio/operator-theme';
import { PromoAPIResponse, PromoData, PromoMessage } from '../../types';
import { OPTIONS } from '../../options';

const DISPLAY_DURATION: number = 5000;
const EXPANDED_DISPLAY_DURATION: number = 7000;
const API_KEY = 'UB1eS3LZQMs9k6xXqAMMiZ1uvhhh2Gck';
const COOLDOWN_TIME: number = 180000; // 3 minutes

export default Vue.component('promo-view', {
    name: 'PromoView',
    props: {
        username: { type: String, required: false },
        onPromoMessage: { type: Function, required: true },
        goToPromo: { type: Function as PropType<(endpoint: string) => void>, required: true },
        strings: { type: Object, required: true },
        deviceId: { type: String, required: true },
        deviceType: { type: String, required: true },
        isPortrait: { type: Boolean, required: true },
        viewHeight: { type: Number, required: true },
        environment: { type: String, required: true },
        theme: { type: Object as PropType<IOperatorTheme>, required: false, default: () => OPTIONS.theme }
    },
    data(): PromoData {
        return {
            timeout: 0,
            cooldownTimeout: 0,
            alertQueue: [],
            isOnCooldown: false,
            isPromoQualificationNotification: false,
            promoInfo: {
                isVisible: false,
                isExpanded: false,
                notificationMessage: 'has won a prize in our latest promo!',
                backgroundColour: '',
                expandedNotificationText: '',
                expandedNotificationAdditionalText: 'Visit our homepage to find out more about this latest promo!',
                webEndpoint: '',
                appEndpoint: ''
            }
        };
    },
    mounted(): void {
        this.onPromoMessage(this.onMessage, this);
    },
    methods: {
        onAlertClick(): void {
            this.promoInfo.isExpanded = !this.promoInfo.isExpanded;

            if (this.promoInfo.isExpanded) {
                window.clearTimeout(this.timeout);
                this.timeout = window.setTimeout(() => {
                    this.promoInfo.isVisible = false;
                    this.promoInfo.isExpanded = false;
                }, EXPANDED_DISPLAY_DURATION);
            }
        },
        navigateToPromo(): void {
            window.clearTimeout(this.timeout);
            window.clearTimeout(this.cooldownTimeout);

            this.promoInfo.isVisible = false;
            this.promoInfo.isExpanded = false;
            if (this.promoInfo.webEndpoint !== '' && this.promoInfo.appEndpoint !== '') {
                this.goToPromo(this.promoInfo.webEndpoint/* , this.promoInfo.appEndpoint */);
            }
        },
        onMessage(data: PromoMessage): void {
            const qsData = QueryString.parse(window.location.search, { ignoreQueryPrefix: true });
            if (!data.isPromo || qsData.shell === 'bingo') {
                return;
            }

            this.queueAlert(data);
        },
        queueAlert(data: PromoMessage): void {
            this.alertQueue.push(data);

            if (this.alertQueue.length > 1) {
                return;
            }

            this.showAlert(data);
        },
        showNextInQueue(): void {
            if (this.alertQueue.length > 0) {
                this.showAlert(this.alertQueue[0]);
            } else {
                this.promoInfo.isVisible = false;
            }
        },
        async showAlert(data: PromoMessage): Promise<void> {
            this.isPromoQualificationNotification = data.PromoNotification !== undefined && data.PromoNotification === true;
            const apiURL = this.getPromoUrl(data);
            let promoInfo = data.promoValue || this.promoInfo;

            if (this.isOnCooldown && !this.isPromoQualificationNotification ||
                (!this.isPromoQualificationNotification && this.isPortrait)) {
                this.forceNextMessage();
                return;
            }

            if (apiURL) {
                try {
                    const apiResponse = await this.getPromoData(apiURL);

                    if (!this.isOnCooldown) {
                        this.isOnCooldown = !this.isPromoQualificationNotification;
                        this.cooldownTimeout = window.setTimeout(() => this.isOnCooldown = false, COOLDOWN_TIME);
                    }

                    if (apiResponse.data && apiResponse.data.properties) {
                        promoInfo = apiResponse.data.properties;
                    }

                    // TSIssue: unclear from typing if backgroundColour could be set to undefined here?
                    this.promoInfo.backgroundColour = promoInfo.expandedNotificationBackgroundColour!;
                    this.promoInfo.expandedNotificationText = promoInfo.expandedNotificationText;
                    this.promoInfo.expandedNotificationAdditionalText = promoInfo.expandedNotificationAdditionalText;
                } catch (e) {
                    this.forceNextMessage();
                    console.error(e);
                    return;
                }
            } else {
                this.promoInfo.backgroundColour = promoInfo.backgroundColour;
                // TSIssue: unclear from typing if expandedNotificationText could be set to undefined here?
                this.promoInfo.expandedNotificationText = promoInfo.expandedNotificationMessage!;
                // TSIssue: unclear from typing if expandedNotificationAdditionalText could be set to undefined here?
                this.promoInfo.expandedNotificationAdditionalText = promoInfo.expandedNotificationAdditionalMessage!;
            }

            this.promoInfo.notificationMessage = data.username ? `${data.username} ${promoInfo.notificationMessage}` : promoInfo.notificationMessage;

            // TSIssue: unclear from typing if webEndpoint could be set to undefined here?
            this.promoInfo.webEndpoint = promoInfo.navigationEndPoint!;
            // TSIssue: unclear from typing if appEndpoint could be set to undefined here?
            this.promoInfo.appEndpoint = promoInfo.navigationPageName!;

            this.promoInfo.isVisible = true;
            this.alertQueue.shift();

            this.timeout = window.setTimeout(this.showNextInQueue, DISPLAY_DURATION);
        },
        forceNextMessage(): void {
            this.alertQueue.shift();
            this.showNextInQueue();
        },
        getPromoData(url: string): AxiosPromise<PromoAPIResponse> {
            const headers = {
                'Content-Type': 'application/x-www-form-urlencoded',
                'X-Tombola-ApiKey': API_KEY,
                'X-Tombola-DeviceIdentifier': this.deviceId,
                'X-Tombola-DeviceType': this.deviceType
            };

            return axios.get(url, { headers });
        },
        getPromoAlertStyle(): { height: string } | void {
            if (!this.promoInfo.isExpanded) {
                return;
            }

            return {
                height: this.isPortrait ? `${this.viewHeight}px` : '100%'
            };
        },
        getPromoUrl(data: PromoMessage): string {
            let endpoint: string = 'winner-notifications';

            if (this.isPromoQualificationNotification) {
                endpoint = 'promotion-qualification-notifications';
            }

            if (data.PromoTicketId !== undefined) {
                data.game = data.PromoTicketId.toLowerCase();
            }

            switch (this.environment) {
                case 'stage':
                    return `https://cms.tombola.com/umbraco/rest/v1/content/published/byurl/?url=stage/arcade/client/${endpoint}/${data.game}`;
                case 'live':
                    return `https://cms.tombola.com/umbraco/rest/v1/content/published/byurl/?url=uk/arcade/client/${endpoint}/${data.game}`;
                case 'dev':
                case 'debug':
                default:
                    return `https://dev-cms.tombola.com/umbraco/rest/v1/content/published/byurl/?url=uk/arcade/client/${endpoint}/${data.game}`;
            }
        }
    }
});